import { readdir, readFile, writeFile } from "node:fs/promises";
const dir = new URL("../migrations/", import.meta.url);
const files = (await readdir(dir))
  .filter(
    (name) => name.endsWith(".sql") && name >= "0018a_review_contract.sql",
  )
  .sort();
let sql =
  "-- GENERATED by npm run db:bundle. Review with SQL_PLAN.md. Never auto-apply to production.\nBEGIN;\n";
sql += `DO $$ BEGIN
 IF to_regclass('public.profiles') IS NULL OR to_regclass('public.certifications') IS NULL
 OR to_regclass('public.trainer_videos') IS NULL OR to_regclass('public.live_sessions') IS NULL
 OR to_regclass('public.trainer_earnings') IS NULL OR to_regclass('public.trainer_busy') IS NULL
 THEN RAISE EXCEPTION 'Historical base schema is incomplete. Stop and review SQL_PLAN.md.'; END IF;
END $$;\n`;
for (const file of files)
  sql += `\n-- FILE: ${file}\n${await readFile(new URL(file, dir), "utf8")}\n`;
sql += "COMMIT;\n";
await writeFile(new URL("../docs/launch/upgrade.sql", import.meta.url), sql);
console.log(
  `${files.length} ordered upgrade migrations bundled; no SQL was executed.`,
);
